#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

# Sets up where Potluck runs: Neon (Postgres 18) and Vercel (Hobby), both in
# Frankfurt. Production runs on Neon's root branch `production`; each preview
# gets its own branch copied from `development`, which is the default branch
# and holds only seed data (docs/adr/0003). Run from the repo root:
#   scripts/setup-hosting.sh
# It writes nothing to .env.local or GitHub: the connection strings live in
# Vercel, put there by Neon's integration.

VERCEL_CLI="vercel@65.5.0"

run_wizard() {

TOTAL_STAGES=6
ENV_FILE=".env.local"

if [[ ! -f package.json || ! -d node_modules ]]; then
  printf 'Run this from the repo root, after npm install.\n' >&2
  exit 1
fi

banner "Potluck hosting: Neon + Vercel in Frankfurt"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Neon: create the project"
open_url "https://console.neon.tech/app/projects"
step "Click New project."
step "Project name: potluck"
step "Postgres version: 18"
step "Cloud provider AWS, region: AWS Europe Central 1 (Frankfurt)."
step "Leave the database name (neondb) as it is, then click Create."
note "Neon makes one root branch, named production. It's also the default branch for now."
note "Production will run on it; never seed it or reset it."
warn "If Postgres 18 or Frankfurt isn't offered, stop here (Ctrl-C) and say so."
pause "Press Enter once the project exists."

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Neon: create development and make it the default"
say "In the potluck project, open Branches in the sidebar."
step "Click New branch."
step "Parent branch: production. Include: Current data (production is still empty)."
step "Name: development"
warn "Untick the option that makes the branch expire (delete itself) after a day."
step "Click Create."
step "Open the development branch, then ⋮ (top right) → Set as default → confirm."
note "Previews are copied from the default branch, so they will start from development."
pause "Press Enter once development exists, never expires, and is the default."

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Neon: seed development"
say "Seed development: it applies the migrations, then loads the seed data."
step "On the project dashboard, click Connect."
step "Branch: development. Database: neondb. Role: neondb_owner."
step "Turn Connection pooling OFF (the host must not contain -pooler)."
step "Copy the connection string (postgresql://…)."
while :; do
  ask_secret DEVELOPMENT_URL "Paste the development connection string:"
  if [[ "$DEVELOPMENT_URL" != postgres*://*neon.tech* ]]; then
    warn "That doesn't look like a Neon connection string. Try again."
  elif [[ "$DEVELOPMENT_URL" == *-pooler* ]]; then
    warn "That's the pooled string. Turn Connection pooling off and copy again."
  else
    break
  fi
done
_host="${DEVELOPMENT_URL#*@}"; _host="${_host%%/*}"
say "Seeding $_host"
if DATABASE_URL="$DEVELOPMENT_URL" npm run --silent db:seed; then
  printf '  %s✓ development migrated and seeded%s\n' "$GREEN" "$RESET"
else
  warn "Seeding failed; the error is above. Fix it, then re-run this wizard."
  exit 1
fi
unset DEVELOPMENT_URL
note "The string isn't saved anywhere. Your .env.local still points at your local Postgres."
pause

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Vercel: import the repo"
open_url "https://vercel.com/new"
step "Under Import Git Repository, pick OrMizrahi12/potluck (grant Vercel access to it if asked)."
step "Project name: potluck. Leave every other setting as it is, then click Deploy."
note "The repo's vercel.json sets Next.js, the build command (migrations first) and region fra1."
note "Node 24 comes from the engines field in package.json."
warn "This first production build of main fails: main doesn't have the app yet. That's expected."
pause "Press Enter once the project exists (even with a failed deployment)."

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Connect Neon to Vercel"
open_url "https://console.neon.tech/app/projects"
step "In the potluck project: Integrations → Vercel → Add → Install from Vercel Marketplace."
step "On Vercel: Install → Link Existing Neon Account → Continue."
step "Give it access to the potluck Vercel project only."
step "In Integrate Neon: Vercel project potluck, Neon project potluck,"
step "  Production branch: production (not development), database neondb, role neondb_owner."
step "Turn ON:  Automatically delete obsolete Neon branches."
step "Leave OFF: Create a branch for your development environment."
step "Click Connect, then Done."
note "Production gets DATABASE_URL (pooled) + DATABASE_URL_UNPOOLED for the root branch;"
note "each preview gets its own preview/<git-branch> branch copied from development."
pause "Press Enter once the integration shows as connected."

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Vercel CLI: sign in and link this folder"
say "Lets Claude read which database each environment got (host names only)."
say "Signing in opens your browser."
npx --yes "$VERCEL_CLI" login
npx --yes "$VERCEL_CLI" link --yes --project potluck
if [[ -f .vercel/project.json ]]; then
  printf '  %s✓ linked%s (.vercel/ is gitignored)\n' "$GREEN" "$RESET"
else
  SKIPPED+=("link this folder: npx $VERCEL_CLI link --project potluck")
  warn "No .vercel/project.json, so the link didn't take."
fi
pause

finish
note "Next: ask Claude to push this branch. The first preview then builds, migrates its"
note "own Neon branch and shows the seeded greeting. Production waits for the merge."
printf '\n'
}

run_wizard "$@"; exit
